`timescale 1ns / 1ps
//==============================================================================
// Project : Program Counter Version 2.0
// File    : next_pc_logic.v
// Author  : Pavan Kumar
//
// Description:
// ------------
// Next Program Counter Logic
//
// This module computes the next Program Counter value based on the
// mutually exclusive control signals generated by the PC Control Unit.
//
// Responsibilities:
//   • Compute sequential PC (PC + PC_INCREMENT)
//   • Select the next PC value
//
// This module contains:
//   • One 32-bit incrementer
//   • One combinational multiplexer
//
// No sequential logic.
// No priority logic.
//==============================================================================

module next_pc_logic #(
    parameter integer XLEN = 32,
    parameter [XLEN-1:0] PC_INCREMENT = 32'd4
)
(
    //----------------------------------------------------------------------
    // Current Program Counter
    //----------------------------------------------------------------------

    input  wire [XLEN-1:0] pc_i,

    //----------------------------------------------------------------------
    // Target Addresses
    //----------------------------------------------------------------------

    input  wire [XLEN-1:0] branch_target_i,
    input  wire [XLEN-1:0] jump_target_i,

    //----------------------------------------------------------------------
    // One-Hot Control Signals
    //----------------------------------------------------------------------

    input  wire seq_sel_i,
    input  wire stall_sel_i,
    input  wire branch_sel_i,
    input  wire jump_sel_i,

    //----------------------------------------------------------------------
    // Next Program Counter
    //----------------------------------------------------------------------

    output reg [XLEN-1:0] next_pc_o
);

    //----------------------------------------------------------------------
    // Local Signals
    //----------------------------------------------------------------------

    wire [XLEN-1:0] pc_plus_increment_w;

    //----------------------------------------------------------------------
    // Sequential Address Calculation
    //----------------------------------------------------------------------

    assign pc_plus_increment_w = pc_i + PC_INCREMENT;

    //----------------------------------------------------------------------
    // Next-PC Selection
    //----------------------------------------------------------------------

    always @(*) begin

        // Default (Sequential Execution)
        next_pc_o = pc_plus_increment_w;

        if (jump_sel_i)
            next_pc_o = jump_target_i;

        else if (branch_sel_i)
            next_pc_o = branch_target_i;

        else if (stall_sel_i)
            next_pc_o = pc_i;

        // seq_sel_i requires no additional assignment because the
        // default path already selects PC + PC_INCREMENT.

    end

endmodule
